import itertools
from collections import deque

def bfs_connected(adj, n, excluded=set()):
    """Check if graph is connected excluding certain vertices."""
    start = None
    for i in range(n):
        if i not in excluded:
            start = i
            break
    if start is None:
        return True  # No vertices left

    visited = {start}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if neighbor not in excluded and neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return all(i in visited for i in range(n) if i not in excluded)

def vertex_connectivity(edges, n):
    """Compute vertex connectivity by trying all pairs of removed vertices."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check base connectivity
    if not bfs_connected(adj, n):
        return 0

    # Try removing single vertices
    for v in range(n):
        if not bfs_connected(adj, n, excluded={v}):
            return 1

    # Try removing pairs of vertices
    for u, v in itertools.combinations(range(n), 2):
        if not bfs_connected(adj, n, excluded={u, v}):
            return 2

    # Try removing triples
    for combo in itertools.combinations(range(n), 3):
        if not bfs_connected(adj, n, excluded=set(combo)):
            return 3

    return 4  # At least 4 (good enough for our purposes)

